async function openMaterial(file){
  if(!token){window.open(file.url||urlFor(file.path),'_blank','noopener');return}
  const tab=window.open('about:blank','_blank');
  try{
    status('Abriendo '+file.name+'…');
    const url='https://api.github.com/repos/'+repo+'/contents/material/'+file.path.split('/').map(encodeURIComponent).join('/')+'?ref=main';
    const response=await fetch(url,{headers:{Accept:'application/vnd.github.raw+json',Authorization:'Bearer '+token,'X-GitHub-Api-Version':'2022-11-28'},cache:'no-store'});
    if(!response.ok)throw Error('GitHub '+response.status);
    const type=/\.pdf$/i.test(file.name)?'application/pdf':/\.md$/i.test(file.name)?'text/markdown;charset=utf-8':response.headers.get('Content-Type')||'application/octet-stream';
    const blob=new Blob([await response.arrayBuffer()],{type}),local=URL.createObjectURL(blob);
    if(tab)tab.location.href=local;
    if(!tab){const a=document.createElement('a');a.href=local;a.download=file.name;a.click()}
    setTimeout(()=>URL.revokeObjectURL(local),300000);
    status('Archivo abierto desde main');
  }catch(error){tab?.close();status(error.message);alert('No se pudo abrir '+file.name+': '+error.message)}
}
