  if(!['Entrada','En curso','Finalizada'].includes(lane))throw Error('Estado de tarea no válido');
  card.lane=lane;card.checked=lane==='Finalizada';const changes=[{kind:'cards',id:card.id}],item=linkedMailItem(card);if(item){item.status=lane==='Finalizada'?'completado':lane==='En curso'?'en curso':'pendiente';touchMailItem(item);changes.push({kind:'academicEdits',id:'overlay'})}changedBatch(changes);
