  const visible=(state.cards||[]).filter(c=>!filter||kanbanSubjects(c).includes(filter));
  const groups=filter?[filter]:[...new Set([...subjects().map(s=>s.name),...visible.flatMap(kanbanSubjects)])].filter(name=>visible.some(c=>kanbanSubjects(c).includes(name)));
  if(!groups.length){root.append(node('p','empty','No hay tareas en esta selección. Añade una tarea o revisa los avisos en Correo académico.'));return}
