    const section=node('section','uc3m-kanban-subject'),course=subjects().find(s=>s.name===name);section.style.setProperty('--subject-color',course?.color||'#000066');section.append(node('h3','',name));
    const grid=node('div','uc3m-kanban-grid'),cards=visible.filter(c=>kanbanSubjects(c).includes(name));
