    const title=field(body,'Título',old?.title||''),course=field(body,'Asignatura','','select'),day=field(body,'Fecha',old?.date||date,'date'),start=field(body,'Inicio',old?.time||'','time'),end=field(body,'Fin',old?.end||'','time'),kind=field(body,'Tipo',old?.kind||'Práctica','select'),room=field(body,'Aula',old?.room||''),group=field(body,'Grupo',old?.group||'');
