function newReport(){
  modal('Nuevo informe UC3M',body=>{
    const title=field(body,'Nombre del informe',''),initial='---\ntello-report: operaciones\nuc3m-report: 1\n---\n\n# Nuevo informe\n\n',editor=markdownEditor(body,initial);
    button(body,'Crear informe',async()=>{try{
      credentials();const name=title.value.trim().replace(/[<>:"/\\|?*]/g,'').replace(/[. ]+$/,'');if(!name)throw Error('Indica un nombre válido');const path='Informes UC3M/'+name+'.md';if((state.reports||[]).some(r=>r.path===path))throw Error('Ya existe un informe con ese nombre');
      const relative='material/'+path.split('/').map(encodeURIComponent).join('/'),url='https://api.github.com/repos/'+repo+'/contents/'+relative;
      try{await api(url+'?ref=main');throw Error('Ya existe un archivo con ese nombre en GitHub')}catch(error){if(!error.message.startsWith('GitHub 404:'))throw error}
      const content=editor.value.replace(/^# Nuevo informe/m,'# '+name),bytes=new TextEncoder().encode(content);let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
      await putContent(relative,btoa(binary),contentBranch,'Crear informe UC3M: '+name);
      state.reports??=[];state.reports.push({name,path,url:relative});state.files??=[];state.files.push({subject:'',name:name+'.md',path,url:relative,size:bytes.length,source:'mobile'});$('#modal').close();changed('reports',path);changed('files',path)
    }catch(error){status(error.message)}},'primary')
  });
}
async function editReport(report){
  try{
    credentials();status('Abriendo informe…');
    const relative='material/'+report.path.split('/').map(encodeURIComponent).join('/');
    const url='https://api.github.com/repos/'+repo+'/contents/'+relative;
    const current=await api(url+'?ref='+contentBranch);
    const content=new TextDecoder().decode(Uint8Array.from(atob(current.content.replace(/\s/g,'')),x=>x.charCodeAt(0)));
    modal('Editar · '+report.name,body=>{
      const editor=markdownEditor(body,content);
      button(body,'Guardar en GitHub',async()=>{
        try{
          status('Guardando informe…');
          const latest=await api(url+'?ref='+contentBranch);
          if(latest.sha!==current.sha)throw Error('El informe cambió en GitHub. Cierra y vuelve a abrirlo.');
          const bytes=new TextEncoder().encode(editor.value);let binary='';
          for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));
          await putContent(relative,btoa(binary),contentBranch,'Editar informe UC3M: '+report.name);
          $('#modal').close();changed('files',report.path);await sync();
        }catch(error){status(error.message);alert(error.message)}
      },'primary');
    });status('Informe abierto');
  }catch(error){status(error.message);alert(error.message)}
}
