function loadMailReview(parsed){
  if(parsed?.schemaVersion!==1||!Array.isArray(parsed.proposals))throw Error('El archivo debe contener schemaVersion: 1 y proposals.');
  if(parsed.proposals.length>500)throw Error('La revisión supera 500 propuestas. Divide el archivo antes de importarlo.');
  const proposals=[],rejected=[];
  for(const p of parsed.proposals){try{if(!window.UC3MMailKanban.validateProposal(state,p))throw Error('Formato de propuesta no válido');const plan=mailPlan(p);if(!plan||!['add','duplicate','review','ignored'].includes(plan.status))throw Error('Formato de propuesta no válido');proposals.push(p)}catch(error){rejected.push(error.message)}}
  mailReview={generatedAt:parsed.generatedAt,proposals,rejected,warnings:Array.isArray(parsed.warnings)?parsed.warnings.filter(x=>typeof x==='string'):[]};tab='mail';render();
}
