  if(!gmailClientId||!geminiKey){gmailSettings();return}
  mailBusy=true;mailProgress='Solicitando acceso de lectura a Gmail…';render();
  try{const result=await window.UC3MGmail.review({clientId:gmailClientId,apiKey:geminiKey,model:geminiModel,subjects:subjects(),onProgress:message=>{mailProgress=String(message);const output=$('#gmail-review-progress');if(output)output.textContent=mailProgress}});loadMailReview(result);mailProgress='Revisión terminada. Comprueba las propuestas antes de incorporarlas.'}
