  const actions=node('div','uc3m-mail-actions'),review=button(actions,mailBusy?'Revisando Gmail…':'Revisar Gmail · últimos 14 días',reviewGmail,'primary');review.disabled=mailBusy;button(actions,'Revisar con ChatGPT',chatGPTMailReview);button(actions,'Importar JSON',importMailReview);button(actions,'Configurar conexión',gmailSettings);head.append(actions);
